CREATE   PROCEDURE [synapse_fo].[usp_Insert_TAXTRANS]
AS
BEGIN

	INSERT INTO [synapse_fo].[TAXTRANS]
	(
		[recid],
		[SinkCreatedOn],
		[SinkModifiedOn],
		[eurotriangulation],
		[exempttax],
		[intracomvat],
		[isoverunderpayment],
		[postponevat],
		[source],
		[taxautogenerated],
		[taxdirection],
		[taxobligationcompany],
		[taxorigin],
		[taxprintdetail],
		[taxtype_mx],
		[unrealizedtax],
		[unrealizedtaxext],
		[reversecharge_w],
		[reversechargeapplies_uk],
		[taxaccounttype],
		[skipledgerposting],
		[sysdatastatecode],
		[currencycode],
		[exemptcode],
		[headingtableid],
		[inventtransid],
		[invoiceid],
		[journalnum],
		[printcode],
		[realizeddate],
		[sourcebaseamountcur],
		[sourcebaseamountcurregulated],
		[sourcecurrencycode],
		[sourcedocumentline],
		[sourcerecid],
		[sourceregulateamountcur],
		[sourcetableid],
		[sourcetaxamountcur],
		[statementid],
		[taxamount],
		[taxamountcur],
		[taxamountrep],
		[taxbaseamount],
		[taxbaseamountcur],
		[taxbaseamountrep],
		[taxbaseqty],
		[taxbook],
		[taxbooksection],
		[taxcode],
		[taxgroup],
		[taxincostprice],
		[taxincostpricecur],
		[taxincostpricerep],
		[taxincostpricemst],
		[taxincostpriceregulated],
		[taxitemgroup],
		[taxjurisdictioncode],
		[taxperiod],
		[taxrepcounter],
		[taxtransrefrecid],
		[taxvalue],
		[transdate],
		[voucher],
		[taxid],
		[vatexemptpct],
		[partytaxid],
		[origintaxtransrecid],
		[exchratedifforigrecid],
		[nopostingsourceregulateamountcur],
		[nopostingtaxamount],
		[nopostingtaxamountcur],
		[nopostingtaxamountrep],
		[reason],
		[reasoncomment],
		[modifieddatetime],
		[modifiedby],
		[createddatetime],
		[createdby],
		[modifiedtransactionid],
		[createdtransactionid],
		[dataareaid],
		[createdon],
		[modifiedon]
	)
	SELECT
		src.[recid],
		src.[SinkCreatedOn],
		src.[SinkModifiedOn],
		src.[eurotriangulation],
		src.[exempttax],
		src.[intracomvat],
		src.[isoverunderpayment],
		src.[postponevat],
		src.[source],
		src.[taxautogenerated],
		src.[taxdirection],
		src.[taxobligationcompany],
		src.[taxorigin],
		src.[taxprintdetail],
		src.[taxtype_mx],
		src.[unrealizedtax],
		src.[unrealizedtaxext],
		src.[reversecharge_w],
		src.[reversechargeapplies_uk],
		src.[taxaccounttype],
		src.[skipledgerposting],
		src.[sysdatastatecode],
		src.[currencycode],
		src.[exemptcode],
		src.[headingtableid],
		src.[inventtransid],
		src.[invoiceid],
		src.[journalnum],
		src.[printcode],
		src.[realizeddate],
		src.[sourcebaseamountcur],
		src.[sourcebaseamountcurregulated],
		src.[sourcecurrencycode],
		src.[sourcedocumentline],
		src.[sourcerecid],
		src.[sourceregulateamountcur],
		src.[sourcetableid],
		src.[sourcetaxamountcur],
		src.[statementid],
		src.[taxamount],
		src.[taxamountcur],
		src.[taxamountrep],
		src.[taxbaseamount],
		src.[taxbaseamountcur],
		src.[taxbaseamountrep],
		src.[taxbaseqty],
		src.[taxbook],
		src.[taxbooksection],
		src.[taxcode],
		src.[taxgroup],
		src.[taxincostprice],
		src.[taxincostpricecur],
		src.[taxincostpricerep],
		src.[taxincostpricemst],
		src.[taxincostpriceregulated],
		src.[taxitemgroup],
		src.[taxjurisdictioncode],
		src.[taxperiod],
		src.[taxrepcounter],
		src.[taxtransrefrecid],
		src.[taxvalue],
		src.[transdate],
		src.[voucher],
		src.[taxid],
		src.[vatexemptpct],
		src.[partytaxid],
		src.[origintaxtransrecid],
		src.[exchratedifforigrecid],
		src.[nopostingsourceregulateamountcur],
		src.[nopostingtaxamount],
		src.[nopostingtaxamountcur],
		src.[nopostingtaxamountrep],
		src.[reason],
		src.[reasoncomment],
		src.[modifieddatetime],
		src.[modifiedby],
		src.[createddatetime],
		src.[createdby],
		src.[modifiedtransactionid],
		src.[createdtransactionid],
		src.[dataareaid],
		src.[createdon],
		src.[modifiedon]
	FROM [staging_fo].[TAXTRANS] src
		LEFT JOIN [synapse_fo].[TAXTRANS] tgt
			ON src.[recid] = tgt.[recid]
			AND src.[dataareaid] = tgt.[dataareaid]
	WHERE tgt.[recid] IS NULL

END
